1	// Package parser implements an AST parser for mini FreeLang
2	package parser
3	
4	import (
5		"fmt"
6	
7		"github.com/user/freelang-evolving-compiler/internal/ast"
8		"github.com/user/freelang-evolving-compiler/internal/lexer"
9	)
10	
11	type Parser struct {
12		l         *lexer.Lexer
13		curToken  ast.Token
14		peekToken ast.Token
15	}
16	
17	// New creates a new parser for the input string
18	func New(input string) *Parser {
19		l := lexer.New(input)
20		p := &Parser{l: l}
21		p.nextToken()
22		p.nextToken()
23		return p
24	}
25	
26	func (p *Parser) nextToken() {
27		p.curToken = p.peekToken
28		p.peekToken = p.l.NextToken()
29	}
30	
31	// ParseProgram parses a complete program
32	func (p *Parser) ParseProgram() (*ast.Node, error) {
33		prog := &ast.Node{
34			Kind:     ast.NodeProgram,
35			Children: []*ast.Node{},
36		}
37	
38		for p.curToken.Type != ast.TokenEOF {
39			stmt, err := p.parseStatement()
40			if err != nil {
41				return nil, err
42			}
43			if stmt != nil {
44				prog.Children = append(prog.Children, stmt)
45			}
46			p.skipSemicolons()
47		}
48	
49		return prog, nil
50	}
51	
52	func (p *Parser) parseStatement() (*ast.Node, error) {
53		switch p.curToken.Type {
54		case ast.TokenLet:
55			return p.parseLetDecl()
56		case ast.TokenFn:
57			return p.parseFnDecl()
58		case ast.TokenIf:
59			return p.parseIfStmt()
60		case ast.TokenFor:
61			return p.parseForStmt()
62		case ast.TokenReturn:
63			return p.parseReturnStmt()
64		case ast.TokenStruct:
65			return p.parseStructDecl()
66		case ast.TokenLBrace:
67			return p.parseBlockStmt()
68		case ast.TokenSemicolon:
69			p.nextToken()
70			return nil, nil
71		default:
72			// Try to parse as expression statement
73			expr, err := p.parseExpression(0)
74			if err != nil {
75				return nil, err
76			}
77			return expr, nil
78		}
79	}
80	
81	func (p *Parser) parseLetDecl() (*ast.Node, error) {
82		letNode := &ast.Node{
83			Kind: ast.NodeLetDecl,
84			Line: p.curToken.Line,
85			Col:  p.curToken.Col,
86		}
87	
88		p.nextToken() // consume 'let'
89	
90		if p.curToken.Type != ast.TokenIdent {
91			return nil, fmt.Errorf("expected identifier after 'let'")
92		}
93	
94		nameNode := &ast.Node{
95			Kind:  ast.NodeIdent,
96			Value: p.curToken.Value,
97			Line:  p.curToken.Line,
98			Col:   p.curToken.Col,
99		}
100		letNode.Children = append(letNode.Children, nameNode)
101	
102		p.nextToken() // consume identifier
103	
104		// Check for type annotation: let x: int = ...
105		if p.curToken.Type == ast.TokenColon {
106			p.nextToken() // consume ':'
107			if p.curToken.Type != ast.TokenIdent {
108				return nil, fmt.Errorf("expected type name after ':'")
109			}
110			nameNode.TypeAnnotation = p.curToken.Value // "int", "bool", "Point", etc.
111			p.nextToken()                              // consume type name
112		}
113	
114		if p.curToken.Type != ast.TokenAssign {
115			return nil, fmt.Errorf("expected '=' after identifier")
116		}
117	
118		p.nextToken() // consume '='
119	
120		expr, err := p.parseExpression(0)
121		if err != nil {
122			return nil, err
123		}
124		letNode.Children = append(letNode.Children, expr)
125	
126		return letNode, nil
127	}
