190	func (p *Parser) parseIfStmt() (*ast.Node, error) {
191		ifNode := &ast.Node{
192			Kind: ast.NodeIfStmt,
193			Line: p.curToken.Line,
194			Col:  p.curToken.Col,
195		}
196	
197		p.nextToken() // consume 'if'
198	
199		cond, err := p.parseExpression(0)
200		if err != nil {
201			return nil, err
202		}
203		ifNode.Children = append(ifNode.Children, cond)
204	
205		if p.curToken.Type != ast.TokenLBrace {
206			return nil, fmt.Errorf("expected '{' after if condition")
207		}
208	
209		body, err := p.parseBlockStmt()
210		if err != nil {
211			return nil, err
212		}
213		ifNode.Children = append(ifNode.Children, body)
214	
215		return ifNode, nil
216	}
