218	func (p *Parser) parseForStmt() (*ast.Node, error) {
219		forNode := &ast.Node{
220			Kind: ast.NodeForStmt,
221			Line: p.curToken.Line,
222			Col:  p.curToken.Col,
223		}
224	
225		p.nextToken() // consume 'for'
226	
227		if p.curToken.Type != ast.TokenIdent {
228			return nil, fmt.Errorf("expected iterator variable")
229		}
230	
231		iter := &ast.Node{
232			Kind:  ast.NodeIdent,
233			Value: p.curToken.Value,
234		}
235		forNode.Children = append(forNode.Children, iter)
236		p.nextToken()
237	
238		if p.curToken.Type != ast.TokenIn {
239			return nil, fmt.Errorf("expected 'in' after iterator")
240		}
241	
242		p.nextToken()
243	
244		rng, err := p.parseExpression(0)
245		if err != nil {
246			return nil, err
247		}
248		forNode.Children = append(forNode.Children, rng)
249	
250		if p.curToken.Type != ast.TokenLBrace {
251			return nil, fmt.Errorf("expected '{' for loop body")
252		}
253	
254		body, err := p.parseBlockStmt()
255		if err != nil {
256			return nil, err
257		}
258		forNode.Children = append(forNode.Children, body)
259	
260		return forNode, nil
261	}
