263	func (p *Parser) parseReturnStmt() (*ast.Node, error) {
264		retNode := &ast.Node{
265			Kind: ast.NodeReturn,
266			Line: p.curToken.Line,
267			Col:  p.curToken.Col,
268		}
269	
270		p.nextToken() // consume 'return'
271	
272		if p.curToken.Type == ast.TokenSemicolon || p.curToken.Type == ast.TokenRBrace {
273			return retNode, nil
274		}
275	
276		expr, err := p.parseExpression(0)
277		if err != nil {
278			return nil, err
279		}
280		retNode.Children = append(retNode.Children, expr)
281	
282		return retNode, nil
283	}
