285	func (p *Parser) parseBlockStmt() (*ast.Node, error) {
286		block := &ast.Node{
287			Kind: ast.NodeBlockStmt,
288			Line: p.curToken.Line,
289			Col:  p.curToken.Col,
290		}
291	
292		p.nextToken() // consume '{'
293	
294		for p.curToken.Type != ast.TokenRBrace && p.curToken.Type != ast.TokenEOF {
295			stmt, err := p.parseStatement()
296			if err != nil {
297				return nil, err
298			}
299			if stmt != nil {
300				block.Children = append(block.Children, stmt)
301			}
302			p.skipSemicolons()
303		}
304	
305		if p.curToken.Type != ast.TokenRBrace {
306			return nil, fmt.Errorf("expected '}'")
307		}
308	
309		p.nextToken() // consume '}'
310	
311		return block, nil
312	}
