314	func (p *Parser) parseExpression(prec int) (*ast.Node, error) {
315		left, err := p.parsePrimary()
316		if err != nil {
317			return nil, err
318		}
319	
320		for prec < p.peekPrecedence() {
321			p.nextToken()
322			left, err = p.parseInfix(left)
323			if err != nil {
324				return nil, err
325			}
326		}
327	
328		return left, nil
329	}
330	
331	func (p *Parser) parsePrimary() (*ast.Node, error) {
332		switch p.curToken.Type {
333		case ast.TokenInt:
334			node := &ast.Node{
335				Kind:  ast.NodeIntLit,
336				Value: p.curToken.Value,
337				Line:  p.curToken.Line,
338				Col:   p.curToken.Col,
339			}
340			return node, nil
341	
342		case ast.TokenIdent:
343			node := &ast.Node{
344				Kind:  ast.NodeIdent,
345				Value: p.curToken.Value,
346				Line:  p.curToken.Line,
347				Col:   p.curToken.Col,
348			}
349			return node, nil
350	
351		case ast.TokenLParen:
352			p.nextToken()
353			expr, err := p.parseExpression(0)
354			if err != nil {
355				return nil, err
356			}
357			if p.curToken.Type != ast.TokenRParen {
358				return nil, fmt.Errorf("expected ')'")
359			}
360			return expr, nil
361	
362		default:
363			return nil, fmt.Errorf("unexpected token: %v", p.curToken.Type)
364		}
365	}
