367	func (p *Parser) parseInfix(left *ast.Node) (*ast.Node, error) {
368		// Handle field access: obj.field
369		if p.curToken.Type == ast.TokenDot {
370			p.nextToken() // consume '.'
371			if p.curToken.Type != ast.TokenIdent {
372				return nil, fmt.Errorf("expected field name after '.'")
373			}
374			return &ast.Node{
375				Kind:     ast.NodeFieldAccess,
376				Value:    p.curToken.Value,
377				Line:     p.curToken.Line,
378				Col:      p.curToken.Col,
379				Children: []*ast.Node{left},
380			}, nil
381		}
382	
383		node := &ast.Node{
384			Kind:     ast.NodeBinaryExpr,
385			Line:     p.curToken.Line,
386			Col:      p.curToken.Col,
387			Value:    p.curToken.Value,
388			Children: []*ast.Node{left},
389		}
390	
391		prec := p.curPrecedence()
392		p.nextToken()
393	
394		right, err := p.parseExpression(prec)
395		if err != nil {
396			return nil, err
397		}
398		node.Children = append(node.Children, right)
399	
400		// Handle function calls
401		if left.Kind == ast.NodeIdent && p.curToken.Type == ast.TokenLParen {
402			call := &ast.Node{
403				Kind:  ast.NodeCallExpr,
404				Value: left.Value,
405			}
406			p.nextToken() // consume '('
407			for p.curToken.Type != ast.TokenRParen {
408				arg, err := p.parseExpression(0)
409				if err != nil {
410					return nil, err
411				}
412				call.Children = append(call.Children, arg)
413				if p.curToken.Type == ast.TokenComma {
414					p.nextToken()
415				}
416			}
417			p.nextToken() // consume ')'
418			return call, nil
419		}
420	
421		return node, nil
422	}
423	
424	func (p *Parser) peekPrecedence() int {
425		return precedence(p.peekToken.Type)
426	}
427	
428	func (p *Parser) curPrecedence() int {
429		return precedence(p.curToken.Type)
430	}
431	
432	func precedence(tok ast.TokenType) int {
433		switch tok {
434		case ast.TokenEq, ast.TokenNe, ast.TokenLt, ast.TokenGt, ast.TokenLe, ast.TokenGe:
435			return 1
436		case ast.TokenPlus, ast.TokenMinus:
437			return 2
438		case ast.TokenStar, ast.TokenSlash:
439			return 3
440		case ast.TokenDotDot:
441			return 4
442		case ast.TokenDot:
443			return 5
444		default:
445			return 0
446		}
447	}
448	
449	func (p *Parser) skipSemicolons() {
450		for p.curToken.Type == ast.TokenSemicolon {
451			p.nextToken()
452		}
453	}
