455	func (p *Parser) parseStructDecl() (*ast.Node, error) {
456		structNode := &ast.Node{
457			Kind: ast.NodeStructDecl,
458			Line: p.curToken.Line,
459			Col:  p.curToken.Col,
460		}
461	
462		p.nextToken() // consume 'struct'
463	
464		if p.curToken.Type != ast.TokenIdent {
465			return nil, fmt.Errorf("expected struct name")
466		}
467	
468		structNode.Value = p.curToken.Value
469		p.nextToken()
470	
471		if p.curToken.Type != ast.TokenLBrace {
472			return nil, fmt.Errorf("expected '{' after struct name")
473		}
474	
475		p.nextToken() // consume '{'
476	
477		// Parse fields
478		for p.curToken.Type != ast.TokenRBrace {
479			field, err := p.parseFieldDecl()
480			if err != nil {
481				return nil, err
482			}
483			structNode.Children = append(structNode.Children, field)
484	
485			if p.curToken.Type == ast.TokenSemicolon {
486				p.nextToken()
487			}
488		}
489	
490		p.nextToken() // consume '}'
491	
492		return structNode, nil
493	}
494	
495	func (p *Parser) parseFieldDecl() (*ast.Node, error) {
496		if p.curToken.Type != ast.TokenIdent {
497			return nil, fmt.Errorf("expected field name")
498		}
499	
500		fieldNode := &ast.Node{
501			Kind:  ast.NodeFieldDecl,
502			Value: p.curToken.Value,
503			Line:  p.curToken.Line,
504			Col:   p.curToken.Col,
505		}
506	
507		p.nextToken() // consume field name
508	
509		if p.curToken.Type != ast.TokenColon {
510			return nil, fmt.Errorf("expected ':' after field name")
511		}
512	
513		p.nextToken() // consume ':'
514	
515		if p.curToken.Type != ast.TokenIdent {
516			return nil, fmt.Errorf("expected field type")
517		}
518	
519		typeNode := &ast.Node{
520			Kind:  ast.NodeIdent,
521			Value: p.curToken.Value,
522			Line:  p.curToken.Line,
523			Col:   p.curToken.Col,
524		}
525		fieldNode.TypeAnnotation = p.curToken.Value // Store type annotation directly
526		fieldNode.Children = append(fieldNode.Children, typeNode)
527	
528		p.nextToken() // consume type
529	
530		return fieldNode, nil
531	}
